import subprocess

def comp_sample(seed, n, k_or_frac, two_pass=False):
    fa="/tmp/tmp.fa"
    with open(fa,'w') as f:
        for i in range(n):
            f.write(f">seq{i+1}\nAAAA\n")
    args=['./executable','sample','-s',str(seed)]
    if two_pass:
        args.append('-2')
    args.extend([fa,str(k_or_frac)])
    out = subprocess.check_output(args, text=True, stderr=subprocess.DEVNULL)
    kept=[]
    for line in out.splitlines():
        if line.startswith('>'):
            kept.append(int(line[1:][3:])-1)
    return sorted(kept)

# Our high method matched for seed11 n4 k2 but not for others. Let's try different LCG variants.
# Perhaps seqtk uses erand48? Or uses random that is seeded differently for 2-pass vs 1-pass.

# Let's try to think about 2-pass mode: -2 option. According to usage, it's "2-pass mode: twice as slow but with much reduced memory"
# That suggests 1-pass is reservoir (memory efficient), 2-pass maybe first pass counts n, second pass samples with probability?
# But we tested -2 with number and got same output as without -2? Let's see:

def sample_both(seed, n, k):
    fa="/tmp/tmp.fa"
    with open(fa,'w') as f:
        for i in range(n):
            f.write(f">seq{i+1}\nAAAA\n")
    out1 = subprocess.check_output(['./executable','sample','-s',str(seed),fa,str(k)], text=True, stderr=subprocess.DEVNULL)
    out2 = subprocess.check_output(['./executable','sample','-s',str(seed),'-2',fa,str(k)], text=True, stderr=subprocess.DEVNULL)
    def parse(out):
        kept=[]
        for line in out.splitlines():
            if line.startswith('>'):
                kept.append(int(line[1:][3:])-1)
        return sorted(kept)
    return parse(out1), parse(out2)

for seed in [11,100]:
    for n,k in [(4,2),(5,3),(10,3)]:
        a,b=sample_both(seed,n,k)
        print(f"seed {seed} n {n} k {k} 1-pass {a} 2-pass {b} same? {a==b}")

# For seed 11 n4 k2, both gave [0,2]
# For seed 11 n5 k3, 1-pass [1,3,4] 2-pass maybe different?
# Let's see:

# Also test fraction with -2: fraction with -2 should be ignored with warning, so same as without -2.

# Let's attempt to reverse engineer 2-pass: first pass counts total n, second pass samples each with probability k/n? But without replacement, need to ensure exactly k samples? Could use sequential sampling: for i in 0..n-1, keep with probability (k - kept)/ (n - i)

def two_pass_sample(seed, n, k):
    # Implementation of sequential sampling without replacement using RNG
    # Common algorithm: for i from 0 to n-1, keep if rand < (k - kept)/(n - i)
    s=seed
    kept=[]
    MOD=1<<64
    for i in range(n):
        s = (s * 6364136223846793005 + 1) & (MOD-1)
        r = (s >> 32) / (1<<32)
        # probability to keep
        if len(kept) < k:
            prob = (k - len(kept)) / (n - i)
            if r < prob:
                kept.append(i)
    return sorted(kept)

def two_pass_low(seed, n, k):
    s=seed
    kept=[]
    MOD=1<<64
    for i in range(n):
        s = (s * 6364136223846793005 + 1) & (MOD-1)
        r = (s & 0xFFFFFFFF) / (1<<32)
        if len(kept) < k:
            prob = (k - len(kept)) / (n - i)
            if r < prob:
                kept.append(i)
    return sorted(kept)

for seed in [11,100]:
    for n,k in [(4,2),(5,3),(10,3)]:
        actual1,actual2 = sample_both(seed,n,k)
        pred_high = two_pass_sample(seed,n,k)
        pred_low = two_pass_low(seed,n,k)
        print(f"2-pass seed {seed} n {n} k {k} actual1 {actual1} actual2 {actual2} pred_high {pred_high} pred_low {pred_low}")

# Let's also test fraction mode with two-pass? It warns and ignores -2, so same.

