#!/usr/bin/env python3
import sys, os, random, math, gzip, collections

VERSION = "1.5-r133"

def open_file(fname, mode='rt'):
    if fname is None or fname == '-':
        return sys.stdin if 'r' in mode else sys.stdout
    if fname.endswith('.gz'):
        return gzip.open(fname, 'rt') if 'r' in mode else gzip.open(fname, 'wt')
    return open(fname, mode)

def parse_fasta_fastq(handle):
    line = handle.readline()
    while line:
        if not line:
            break
        line=line.rstrip('\n')
        if not line:
            line=handle.readline()
            continue
        if line.startswith('>'):
            header=line[1:]
            parts=header.split(None,1)
            name=parts[0] if parts else ""
            comment=parts[1] if len(parts)>1 else ""
            seq_parts=[]
            while True:
                nxt=handle.readline()
                if not nxt:
                    seq=''.join(seq_parts)
                    yield {'name':name,'comment':comment,'header':header,'seq':seq,'qual':None,'is_fq':False}
                    line=None
                    break
                if nxt.startswith('>'):
                    seq=''.join(seq_parts)
                    yield {'name':name,'comment':comment,'header':header,'seq':seq,'qual':None,'is_fq':False}
                    line=nxt
                    break
                elif nxt.startswith('@'):
                    seq=''.join(seq_parts)
                    yield {'name':name,'comment':comment,'header':header,'seq':seq,'qual':None,'is_fq':False}
                    line=nxt
                    break
                else:
                    seq_parts.append(nxt.strip())
            if line is None:
                break
            continue
        elif line.startswith('@'):
            header=line[1:]
            parts=header.split(None,1)
            name=parts[0] if parts else ""
            comment=parts[1] if len(parts)>1 else ""
            seq_line=handle.readline()
            if not seq_line:
                break
            seq=seq_line.rstrip('\n')
            plus=handle.readline()
            if not plus:
                break
            qual_line=handle.readline()
            if not qual_line:
                break
            qual=qual_line.rstrip('\n')
            while len(qual) < len(seq):
                extra=handle.readline()
                if not extra:
                    break
                qual+=extra.rstrip('\n')
            yield {'name':name,'comment':comment,'header':header,'seq':seq,'qual':qual,'is_fq':True}
            line=handle.readline()
            continue
        else:
            line=handle.readline()
            continue

def reverse_complement(seq):
    comp={'A':'T','a':'t','C':'G','c':'g','G':'C','g':'c','T':'A','t':'a','U':'A','u':'a','M':'K','m':'k','K':'M','k':'m','R':'Y','r':'y','Y':'R','y':'r','W':'W','w':'w','S':'S','s':'s','V':'B','v':'b','B':'V','b':'v','H':'D','h':'d','D':'H','d':'h','N':'N','n':'n'}
    return ''.join(comp.get(b,b) for b in seq)[::-1]

def load_bed(fname):
    d={}
    try:
        with open_file(fname,'rt') as f:
            for line in f:
                line=line.strip()
                if not line or line.startswith('#'):
                    continue
                fields=line.split()
                if len(fields)<3:
                    continue
                chrom=fields[0]
                try:
                    s=int(fields[1]); e=int(fields[2])
                except:
                    continue
                d.setdefault(chrom, []).append((s,e))
    except:
        pass
    return d

def load_bed_for_subseq(fname):
    bed_dict={}
    names=set()
    is_bed=None
    lines=[]
    with open_file(fname,'rt') as f:
        for line in f:
            line=line.strip()
            if not line or line.startswith('#'):
                continue
            lines.append(line)
    if not lines:
        return False,set(),[]
    first=lines[0].split()
    if len(first)>=3:
        try:
            int(first[1]); int(first[2]); is_bed=True
        except:
            is_bed=False
    else:
        is_bed=False
    order=[]
    if is_bed:
        for line in lines:
            fields=line.split()
            if len(fields)<3:
                continue
            chrom=fields[0]
            try:
                s=int(fields[1]); e=int(fields[2])
            except:
                continue
            strand='+'
            if len(fields)>=4 and fields[3] in ('+','-'):
                strand=fields[3]
            elif len(fields)>=6 and fields[5] in ('+','-'):
                strand=fields[5]
            bed_dict.setdefault(chrom, []).append((s,e,strand))
            order.append((chrom,s,e,strand))
        return True, bed_dict, order
    else:
        for line in lines:
            name=line.split()[0]
            names.add(name)
            order.append(name)
        return False, names, order

def mask_bed(name, seq, bed_dict):
    if name not in bed_dict:
        return seq
    lst=list(seq)
    for s,e in bed_dict[name]:
        s=max(0,s); e=min(len(lst),e)
        for i in range(s,e):
            lst[i]=lst[i].lower()
    return ''.join(lst)

def comp_seq(seq):
    up=seq.upper()
    length=len(seq)
    A=up.count('A')
    C=up.count('C')
    G=up.count('G')
    T=up.count('T')+up.count('U')
    two=sum(up.count(b) for b in "MRWSYK")
    three=sum(up.count(b) for b in "VHDB")
    N_calc=length-(A+C+G+T+two+three)
    if N_calc<0:
        N_calc=0
    first_set=set("CY")
    second_set=set("GR")
    cg=0
    for i in range(len(up)-1):
        if up[i] in first_set and up[i+1] in second_set:
            cg+=1
    cg2=cg*2
    transv=sum(up.count(b) for b in "MWSK")
    transi=sum(up.count(b) for b in "RY")
    last=0
    for i in range(len(up)-1):
        if up[i] in first_set and up[i+1] in second_set:
            if up[i] in "YR":
                last+=1
            if up[i+1] in "YR":
                last+=1
    return [length,A,C,G,T,two,three,N_calc,cg2,transv,transi,last]

