                pos_base[idx]['N']+=1; all_base['N']+=1
        for idx,qc in enumerate(qual):
            q=ord(qc)-33
            qual_all[q]+=1
            pos_qdist[idx][q]+=1
            pos_qual_sum[idx]+=q
