def mergepe_command(args):
    if len(args)<2:
        sys.stderr.write("Usage: seqtk mergepe <in1.fq> <in2.fq>\n"); sys.exit(1)
    f1=args[0]; f2=args[1]
    try:
        h1=open_file(f1,'rt'); h2=open_file(f2,'rt')
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    gen1=parse_fasta_fastq(h1); gen2=parse_fasta_fastq(h2)
    while True:
        try:
            r1=next(gen1)
        except StopIteration:
            r1=None
        try:
            r2=next(gen2)
        except StopIteration:
            r2=None
        if r1 is None and r2 is None:
            break
        if r1:
            if r1['is_fq']:
                print(f"@{r1['header']}\n{r1['seq']}\n+\n{r1['qual']}")
            else:
                print(f">{r1['header']}\n{r1['seq']}")
        if r2:
            if r2['is_fq']:
                print(f"@{r2['header']}\n{r2['seq']}\n+\n{r2['qual']}")
            else:
                print(f">{r2['header']}\n{r2['seq']}")
    h1.close(); h2.close()

def split_command(args):
    n_files=10; line_len=0; i=0; prefix=None; input_file=None
    while i < len(args):
        arg=args[i]
        if arg=='-n':
            i+=1
            if i < len(args):
                try:
                    n_files=int(args[i])
                except:
                    n_files=10
                i+=1
            else:
                break
        elif arg.startswith('-n'):
            try:
                n_files=int(arg[2:])
            except:
                n_files=10
            i+=1
        elif arg=='-l':
            i+=1
            if i < len(args):
                try:
                    line_len=int(args[i])
                except:
                    line_len=0
                i+=1
            else:
                break
        elif arg.startswith('-l'):
            try:
                line_len=int(arg[2:])
            except:
                line_len=0
            i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"split: invalid option -- '{arg[1]}'\n"); sys.exit(1)
        else:
            if prefix is None:
                prefix=arg
            elif input_file is None:
                input_file=arg
            i+=1
    if prefix is None or input_file is None:
        sys.stderr.write("Usage: seqtk split [options] <prefix> <in.fa>\nOptions:\n  -n INT    number of files [10]\n  -l INT    line length [0]\n")
        sys.exit(1)
    try:
        handle=open_file(input_file,'rt')
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    out_handles=[]
    for idx in range(n_files):
        fname=f"{prefix}.{idx+1:05d}.fa"
        out_handles.append(open(fname,'w'))
    seq_idx=0
    for rec in parse_fasta_fastq(handle):
        file_idx=seq_idx % n_files
        oh=out_handles[file_idx]
        if rec['is_fq']:
            oh.write(f"@{rec['header']}\n{rec['seq']}\n+\n{rec['qual']}\n")
        else:
            oh.write(f">{rec['header']}\n")
            if line_len==0:
                oh.write(f"{rec['seq']}\n")
            else:
                for k in range(0,len(rec['seq']),line_len):
                    oh.write(f"{rec['seq'][k:k+line_len]}\n")
        seq_idx+=1
    for h in out_handles:
        h.close()
    handle.close()

def trimfq_command_real(args):
    q_thr=0.05; min_len=30; left=0; right=0; retain5=0; force_fq=False; i=0; input_file=None
    while i < len(args):
        arg=args[i]
        if arg=='-q':
            i+=1
            if i < len(args):
                try:
                    q_thr=float(args[i])
                except:
                    q_thr=0.05
                i+=1
            else:
                break
        elif arg.startswith('-q'):
            try:
                q_thr=float(arg[2:])
            except:
                q_thr=0.05
            i+=1
        elif arg=='-l':
            i+=1
            if i < len(args):
                try:
                    min_len=int(args[i])
                except:
                    min_len=30
                i+=1
            else:
                break
        elif arg.startswith('-l'):
            try:
                min_len=int(arg[2:])
            except:
                min_len=30
            i+=1
        elif arg=='-b':
            i+=1
            if i < len(args):
                try:
                    left=int(args[i])
                except:
                    left=0
                i+=1
            else:
                break
        elif arg.startswith('-b'):
            try:
                left=int(arg[2:])
            except:
                left=0
            i+=1
        elif arg=='-e':
            i+=1
            if i < len(args):
                try:
                    right=int(args[i])
                except:
                    right=0
                i+=1
            else:
                break
        elif arg.startswith('-e'):
            try:
                right=int(arg[2:])
            except:
                right=0
            i+=1
        elif arg=='-L':
            i+=1
            if i < len(args):
                try:
                    retain5=int(args[i])
                except:
                    retain5=0
                i+=1
            else:
                break
        elif arg.startswith('-L'):
            try:
                retain5=int(arg[2:])
            except:
                retain5=0
            i+=1
        elif arg=='-Q':
            force_fq=True; i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"trimfq: invalid option -- '{arg[1]}'\n"); sys.exit(1)
        else:
            input_file=arg; i+=1
    if input_file is None:
        handle=sys.stdin
    else:
        try:
            handle=open_file(input_file,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    if q_thr>0:
        Q_thr=-10*math.log10(q_thr)
    else:
        Q_thr=0
    for rec in parse_fasta_fastq(handle):
        seq=rec['seq']; qual=rec['qual']; is_fq=rec['is_fq']
        if left>0 or right>0 or retain5>0:
            ns=seq; nq=qual
            if left>0:
                ns=ns[left:]; nq=nq[left:] if nq else nq
            if right>0:
                if right<=len(ns):
                    ns=ns[:-right] if right>0 else ns
                    nq=nq[:-right] if nq and right>0 else nq
                else:
                    ns=""; nq=""
            if retain5>0:
                ns=ns[:retain5]; nq=nq[:retain5] if nq else nq
            if is_fq or force_fq:
                if not nq:
                    nq='I'*len(ns)
                print(f"@{rec['header']}\n{ns}\n+\n{nq}")
            else:
                if force_fq:
                    if not nq:
                        nq='I'*len(ns)
                    print(f"@{rec['header']}\n{ns}\n+\n{nq}")
                else:
                    print(f">{rec['header']}\n{ns}")
            continue
        if not qual:
            # FASTA
            if len(seq)>min_len and min_len>0:
                ns=seq[:min_len]
            else:
                ns=seq
            print(f">{rec['header']}\n{ns}")
            continue
        Q_scores=[ord(c)-33 for c in qual]
        l=0
        while l < len(Q_scores) and Q_scores[l] < Q_thr:
            l+=1
            if len(seq)-l < min_len:
                break
        r=len(Q_scores)-1
        while r>=l and Q_scores[r] < Q_thr:
            r-=1
            if r-l+1 < min_len:
                break
        if l>r:
            ns=""; nq=""
        else:
            ns=seq[l:r+1]; nq=qual[l:r+1]
        if len(ns) > min_len and min_len>0:
            ns=ns[:min_len]; nq=nq[:min_len]
        print(f"@{rec['header']}\n{ns}\n+\n{nq}")
    if handle is not sys.stdin:
        handle.close()

