    # Simplified: find N tracts (consecutive N/n) of length >= n, and cut sequence at those tracts.
    # For gaps_only, output BED: chrom, start, end of N tracts (0-based?)

    for rec in parse_fasta_fastq(handle):
        seq=rec['seq']
        name=rec['name']
        # Find N tracts
        # We'll scan for N/n
        tracts=[]
        in_n=False
        start=0
        for idx,ch in enumerate(seq):
            if ch.upper()=='N':
                if not in_n:
                    in_n=True
                    start=idx
            else:
                if in_n:
                    in_n=False
                    end=idx
                    if end-start >= n:
                        tracts.append((start,end))
        if in_n:
            end=len(seq)
