            for line in f:
                line=line.strip()
                if not line or line.startswith('#'):
                    continue
                fields=line.split()
                if len(fields)<3:
                    continue
                chrom=fields[0]
                try:
                    s=int(fields[1]); e=int(fields[2])
                except:
