        else:
            is_frac=False
            num=int(val)
    except:
        is_frac=False
        num=0
    if is_frac and two_pass:
        sys.stderr.write("[W::stk_sample] when sampling a fraction, option -2 is ignored.")
    try:
        handle=open_file(input_file,'rt')
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    rnd=random.Random(seed)
    if is_frac:
        for rec in parse_fasta_fastq(handle):
            if rnd.random() < frac:
                if rec['is_fq']:
                    print(f"@{rec['header']}\n{rec['seq']}\n+\n{rec['qual']}")
                else:
                    print(f">{rec['header']}\n{rec['seq']}")
    else:
        k=num
        # Reservoir sampling
        reservoir=[]
        for idx, rec in enumerate(parse_fasta_fastq(handle)):
            if idx < k:
                reservoir.append(rec)
            else:
                j=rnd.randint(0, idx)
                if j < k:
                    reservoir[j]=rec
        for rec in reservoir:
            if rec['is_fq']:
                print(f"@{rec['header']}\n{rec['seq']}\n+\n{rec['qual']}")
            else:
                print(f">{rec['header']}\n{rec['seq']}")
    if handle is not sys.stdin:
        handle.close()

