            i+=1
        elif arg=='-L':
            i+=1
            if i < len(args):
                try:
                    retain5=int(args[i])
                except:
                    retain5=0
                i+=1
            else:
                break
        elif arg.startswith('-L'):
            try:
                retain5=int(arg[2:])
            except:
                retain5=0
            i+=1
        elif arg=='-Q':
            force_fq=True; i+=1
        elif arg.startswith('-'):
