    else:
        Q_thr=0
    for rec in parse_fasta_fastq(handle):
        seq=rec['seq']; qual=rec['qual']; is_fq=rec['is_fq']
        if left>0 or right>0 or retain5>0:
            ns=seq; nq=qual
            if left>0:
                ns=ns[left:]; nq=nq[left:] if nq else nq
            if right>0:
                if right<=len(ns):
                    ns=ns[:-right] if right>0 else ns
                    nq=nq[:-right] if nq and right>0 else nq
                else:
                    ns=""; nq=""
            if retain5>0:
                ns=ns[:retain5]; nq=nq[:retain5] if nq else nq
            if is_fq or force_fq:
                if not nq:
                    nq='I'*len(ns)
                print(f"@{rec['header']}\n{ns}\n+\n{nq}")
            else:
                if force_fq:
                    if not nq:
                        nq='I'*len(ns)
                    print(f"@{rec['header']}\n{ns}\n+\n{nq}")
                else:
                    print(f">{rec['header']}\n{ns}")
            continue
        if not qual:
            # FASTA
            if len(seq)>min_len and min_len>0:
                ns=seq[:min_len]
            else:
                ns=seq
            print(f">{rec['header']}\n{ns}")
            continue
        Q_scores=[ord(c)-33 for c in qual]
        l=0
        while l < len(Q_scores) and Q_scores[l] < Q_thr:
            l+=1
            if len(seq)-l < min_len:
                break
        r=len(Q_scores)-1
        while r>=l and Q_scores[r] < Q_thr:
            r-=1
            if r-l+1 < min_len:
                break
        if l>r:
            ns=""; nq=""
        else:
            ns=seq[l:r+1]; nq=qual[l:r+1]
        if len(ns) > min_len and min_len>0:
            ns=ns[:min_len]; nq=nq[:min_len]
        print(f"@{rec['header']}\n{ns}\n+\n{nq}")
