def mutfa_command_real(args):
    if len(args)<2:
        sys.stderr.write("Usage: seqtk mutfa <in.fa> <in.snp>\n\nNote: <in.snp> contains at least four columns per line which are:\n      'chr  1-based-pos  any  base-changed-to'.\n")
        sys.exit(1)
    fa=args[0]; snp=args[1]
    mut_dict={}
    try:
        with open_file(snp,'rt') as f:
            for line in f:
                line=line.strip()
                if not line or line.startswith('#'):
                    continue
                fields=line.split()
                if len(fields)<4:
                    continue
                chrom=fields[0]
                try:
                    pos=int(fields[1])
                except:
                    continue
                new_base=fields[3]
                mut_dict.setdefault(chrom, {})[pos]=new_base
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)

    try:
        handle=open_file(fa,'rt')
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)

    for rec in parse_fasta_fastq(handle):
        name=rec['name']
        seq=list(rec['seq'])
        if name in mut_dict:
            for pos,new_base in mut_dict[name].items():
                # 1-based
                idx=pos-1
                if 0 <= idx < len(seq):
                    seq[idx]=new_base
        print(f">{rec['header']}\n{''.join(seq)}")

    if handle is not sys.stdin:
        handle.close()

