        # We'll try to extract base by removing trailing /1 or /2, _1,_2, .1,.2, or space +1/2
        # Also handle "seq1/1" where name is "seq1/1", base "seq1"

        base = header
        # Try to detect suffix
        # If ends with /1 or /2
        if base.endswith('/1') or base.endswith('/2'):
            base=base[:-2]
        elif base.endswith('_1') or base.endswith('_2'):
            base=base[:-2]
        elif base.endswith('.1') or base.endswith('.2'):
            base=base[:-2]
        elif ' ' in base:
            # If header contains space, first word is name, which may include /1
            # Actually name is first word, we already have rec['name']
