            i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"split: invalid option -- '{arg[1]}'\n"); sys.exit(1)
        else:
            if prefix is None:
                prefix=arg
            elif input_file is None:
                input_file=arg
            i+=1
    if prefix is None or input_file is None:
        sys.stderr.write("Usage: seqtk split [options] <prefix> <in.fa>\nOptions:\n  -n INT    number of files [10]\n  -l INT    line length [0]\n")
        sys.exit(1)
    try:
        handle=open_file(input_file,'rt')
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    out_handles=[]
    for idx in range(n_files):
        fname=f"{prefix}.{idx+1:05d}.fa"
        out_handles.append(open(fname,'w'))
    seq_idx=0
    for rec in parse_fasta_fastq(handle):
        file_idx=seq_idx % n_files
        oh=out_handles[file_idx]
        if rec['is_fq']:
            oh.write(f"@{rec['header']}\n{rec['seq']}\n+\n{rec['qual']}\n")
        else:
            oh.write(f">{rec['header']}\n")
            if line_len==0:
                oh.write(f"{rec['seq']}\n")
            else:
                for k in range(0,len(rec['seq']),line_len):
                    oh.write(f"{rec['seq'][k:k+line_len]}\n")
        seq_idx+=1
    for h in out_handles:
        h.close()
    handle.close()

def trimfq_command_real(args):
    q_thr=0.05; min_len=30; left=0; right=0; retain5=0; force_fq=False; i=0; input_file=None
    while i < len(args):
        arg=args[i]
        if arg=='-q':
            i+=1
            if i < len(args):
                try:
                    q_thr=float(args[i])
                except:
                    q_thr=0.05
                i+=1
            else:
                break
        elif arg.startswith('-q'):
            try:
                q_thr=float(arg[2:])
            except:
                q_thr=0.05
            i+=1
        elif arg=='-l':
            i+=1
            if i < len(args):
                try:
                    min_len=int(args[i])
                except:
                    min_len=30
                i+=1
            else:
                break
        elif arg.startswith('-l'):
            try:
                min_len=int(arg[2:])
            except:
                min_len=30
            i+=1
        elif arg=='-b':
            i+=1
            if i < len(args):
                try:
                    left=int(args[i])
                except:
                    left=0
                i+=1
            else:
                break
        elif arg.startswith('-b'):
            try:
                left=int(arg[2:])
            except:
                left=0
            i+=1
        elif arg=='-e':
            i+=1
            if i < len(args):
                try:
                    right=int(args[i])
                except:
                    right=0
                i+=1
            else:
                break
        elif arg.startswith('-e'):
            try:
                right=int(arg[2:])
            except:
                right=0
            i+=1
        elif arg=='-L':
            i+=1
            if i < len(args):
                try:
                    retain5=int(args[i])
                except:
                    retain5=0
                i+=1
            else:
                break
        elif arg.startswith('-L'):
            try:
                retain5=int(arg[2:])
            except:
                retain5=0
            i+=1
        elif arg=='-Q':
            force_fq=True; i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"trimfq: invalid option -- '{arg[1]}'\n"); sys.exit(1)
        else:
            input_file=arg; i+=1
    if input_file is None:
        handle=sys.stdin
    else:
        try:
            handle=open_file(input_file,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    if q_thr>0:
        Q_thr=-10*math.log10(q_thr)
    else:
        Q_thr=0
    for rec in parse_fasta_fastq(handle):
        seq=rec['seq']; qual=rec['qual']; is_fq=rec['is_fq']
        if left>0 or right>0 or retain5>0:
            ns=seq; nq=qual
            if left>0:
                ns=ns[left:]; nq=nq[left:] if nq else nq
            if right>0:
                if right<=len(ns):
                    ns=ns[:-right] if right>0 else ns
                    nq=nq[:-right] if nq and right>0 else nq
                else:
                    ns=""; nq=""
            if retain5>0:
                ns=ns[:retain5]; nq=nq[:retain5] if nq else nq
            if is_fq or force_fq:
                if not nq:
                    nq='I'*len(ns)
                print(f"@{rec['header']}\n{ns}\n+\n{nq}")
            else:
                if force_fq:
                    if not nq:
                        nq='I'*len(ns)
                    print(f"@{rec['header']}\n{ns}\n+\n{nq}")
                else:
                    print(f">{rec['header']}\n{ns}")
            continue
        if not qual:
            if len(seq)>min_len and min_len>0:
                ns=seq[:min_len]
            else:
                ns=seq
            print(f">{rec['header']}\n{ns}")
            continue
        Q_scores=[ord(c)-33 for c in qual]
        l=0
        while l < len(Q_scores) and Q_scores[l] < Q_thr:
            l+=1
            if len(seq)-l < min_len:
                break
        r=len(Q_scores)-1
        while r>=l and Q_scores[r] < Q_thr:
            r-=1
            if r-l+1 < min_len:
                break
        if l>r:
            ns=""; nq=""
        else:
            ns=seq[l:r+1]; nq=qual[l:r+1]
        if len(ns) > min_len and min_len>0:
            ns=ns[:min_len]; nq=nq[:min_len]
        print(f"@{rec['header']}\n{ns}\n+\n{nq}")
    if handle is not sys.stdin:
        handle.close()

def hety_command_real(args):
    w=50000; t=5; masked=False; i=0; input_file=None
    while i < len(args):
        arg=args[i]
        if arg=='-w':
            i+=1
            if i < len(args):
                try:
                    w=int(args[i])
                except:
                    w=50000
                i+=1
            else:
                break
        elif arg.startswith('-w'):
            try:
                w=int(arg[2:])
            except:
                w=50000
            i+=1
        elif arg=='-t':
            i+=1
            if i < len(args):
                try:
                    t=int(args[i])
                except:
                    t=5
                i+=1
            else:
                break
        elif arg.startswith('-t'):
            try:
                t=int(arg[2:])
            except:
                t=5
            i+=1
        elif arg=='-m':
            masked=True; i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"hety: invalid option -- '{arg[1]}'\n"); sys.exit(1)
        else:
            input_file=arg; i+=1
    if input_file is None:
        handle=sys.stdin
    else:
        try:
            handle=open_file(input_file,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    for rec in parse_fasta_fastq(handle):
        seq=rec['seq']
        name=rec['name']
        L=len(seq)
        pos=0
        while pos < L:
            end=min(pos+w, L)
            window_seq=seq[pos:end]
            effective=0
            hets=0
            for b in window_seq:
                if masked and b.islower():
                    continue
                bu=b.upper()
                if bu in "ACGTMRWSYK":
                    effective+=1
                    if bu in "MRWSYK":
                        hets+=1
            rate = (w * hets / effective) if effective>0 else 0
            print(f"{name}\t{pos}\t{end}\t{rate:.2f}\t{effective}\t{hets}")
            pos=end
    if handle is not sys.stdin:
        handle.close()

def gc_command_real(args):
    at=False; min_frac=0.60; min_len=20; xdrop=10.0; i=0; input_file=None
    while i < len(args):
        arg=args[i]
        if arg=='-w':
            at=True; i+=1
        elif arg=='-f':
            i+=1
            if i < len(args):
                try:
                    min_frac=float(args[i])
                except:
                    min_frac=0.60
                i+=1
            else:
                break
        elif arg.startswith('-f'):
            try:
                min_frac=float(arg[2:])
            except:
                min_frac=0.60
            i+=1
        elif arg=='-l':
            i+=1
            if i < len(args):
                try:
                    min_len=int(args[i])
                except:
                    min_len=20
                i+=1
            else:
                break
        elif arg.startswith('-l'):
            try:
                min_len=int(arg[2:])
            except:
                min_len=20
            i+=1
        elif arg=='-x':
            i+=1
            if i < len(args):
                try:
                    xdrop=float(args[i])
                except:
                    xdrop=10.0
                i+=1
            else:
                break
        elif arg.startswith('-x'):
            try:
                xdrop=float(arg[2:])
            except:
                xdrop=10.0
            i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"gc: invalid option -- '{arg[1]}'\n"); sys.exit(1)
        else:
            input_file=arg; i+=1
    if input_file is None:
        handle=sys.stdin
    else:
        try:
            handle=open_file(input_file,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)

    def find_regions(seq, min_frac, min_len, xdrop, at):
        L=len(seq)
        up=seq.upper()
        if at:
            is_gc=[1 if b in 'AT' else 0 for b in up]
        else:
            is_gc=[1 if b in 'GC' else 0 for b in up]
        scores=[g - min_frac for g in is_gc]
        regions=[]
        i=0
        while i < L:
            # search best segment
            best_score=-1e9
            best_s=-1
            best_e=-1
            # For each start in remaining, compute max scoring segment with dropoff
            for start in range(i, L):
                cum=0
                max_cum=0
                max_end=start
                for end in range(start, L):
                    cum+=scores[end]
                    if cum>max_cum:
                        max_cum=cum
                        max_end=end+1
                    if max_cum - cum > xdrop:
                        break
                if max_cum>best_score and max_end-start>=min_len:
                    best_score=max_cum
                    best_s=start
                    best_e=max_end
            if best_s==-1:
                break
            gc_count=sum(is_gc[best_s:best_e])
            regions.append((best_s,best_e,gc_count))
            i=best_e
        return regions

    for rec in parse_fasta_fastq(handle):
        seq=rec['seq']
        name=rec['name']
        regs=find_regions(seq, min_frac, min_len, xdrop, at)
        for s,e,gc_count in regs:
            print(f"{name}\t{s}\t{e}\t{gc_count}")

    if handle is not sys.stdin:
        handle.close()

def mutfa_command_real(args):
    if len(args)<2:
        sys.stderr.write("Usage: seqtk mutfa <in.fa> <in.snp>\n\nNote: <in.snp> contains at least four columns per line which are:\n      'chr  1-based-pos  any  base-changed-to'.\n")
        sys.exit(1)
    fa=args[0]; snp=args[1]
    mut={}
    try:
        with open_file(snp,'rt') as f:
            for line in f:
                line=line.strip()
                if not line or line.startswith('#'):
                    continue
                fields=line.split()
                if len(fields)<4:
                    continue
                chrom=fields[0]
                try:
                    pos=int(fields[1])
                except:
                    continue
                nb=fields[3]
                mut.setdefault(chrom, {})[pos]=nb
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    try:
        handle=open_file(fa,'rt')
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    for rec in parse_fasta_fastq(handle):
        name=rec['name']
        seq=list(rec['seq'])
        if name in mut:
            for p,b in mut[name].items():
                idx=p-1
                if 0 <= idx < len(seq):
                    seq[idx]=b
        print(f">{rec['header']}\n{''.join(seq)}")
    if handle is not sys.stdin:
        handle.close()

def mergefa_command_real(args):
    q_thr=0; intersect=False; to_lower=False; rand_het=False; suppress_hets=False
    i=0; f1=None; f2=None
    while i < len(args):
        arg=args[i]
        if arg=='-q':
            i+=1
            if i < len(args):
                try:
                    q_thr=int(args[i])
                except:
                    q_thr=0
                i+=1
            else:
                break
        elif arg.startswith('-q'):
            try:
                q_thr=int(arg[2:])
            except:
                q_thr=0
            i+=1
        elif arg=='-i':
            intersect=True; i+=1
        elif arg=='-m':
            to_lower=True; i+=1
        elif arg=='-r':
            rand_het=True; i+=1
        elif arg=='-h':
            suppress_hets=True; i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"mergefa: invalid option -- '{arg[1]}'\n"); sys.exit(1)
        else:
            if f1 is None:
                f1=arg
            elif f2 is None:
                f2=arg
            i+=1
    if f1 is None or f2 is None:
        sys.stderr.write("Usage: seqtk mergefa [options] <in1.fa> <in2.fa>\n\nOptions: -q INT   quality threshold [0]\n         -i       take intersection\n         -m       convert to lowercase when one of the input base is N\n         -r       pick a random allele from het\n         -h       suppress hets in the input\n")
        sys.exit(1)
    def load_dict(fname):
        d={}
        try:
            h=open_file(fname,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
        for rec in parse_fasta_fastq(h):
            d[rec['name']]=rec['seq']
        if h is not sys.stdin:
            h.close()
        return d
    dict1=load_dict(f1); dict2=load_dict(f2)
    all_names=set(dict1.keys()) | set(dict2.keys()) if not intersect else set(dict1.keys()) & set(dict2.keys())
    rnd=random.Random(11)
    iupac_to_set={
        'A':{'A'},'C':{'C'},'G':{'G'},'T':{'T'},'U':{'T'},
        'M':{'A','C'},'R':{'A','G'},'W':{'A','T'},'S':{'C','G'},'Y':{'C','T'},'K':{'G','T'},
        'V':{'A','C','G'},'H':{'A','C','T'},'D':{'A','G','T'},'B':{'C','G','T'},'N':{'A','C','G','T'},
    }
    set_to_iupac={
        frozenset({'A'}):'A',
        frozenset({'C'}):'C',
        frozenset({'G'}):'G',
        frozenset({'T'}):'T',
        frozenset({'A','C'}):'M',
        frozenset({'A','G'}):'R',
        frozenset({'A','T'}):'W',
        frozenset({'C','G'}):'S',
        frozenset({'C','T'}):'Y',
        frozenset({'G','T'}):'K',
        frozenset({'A','C','G'}):'V',
        frozenset({'A','C','T'}):'H',
        frozenset({'A','G','T'}):'D',
        frozenset({'C','G','T'}):'B',
        frozenset({'A','C','G','T'}):'N',
    }
    same=0; diff=0; hom_het=0; het_hom=0; het_het=0
    for name in all_names:
        seq1=dict1.get(name,"")
        seq2=dict2.get(name,"")
        if not seq1:
            seq1=seq2
            seq2=""
        if not seq2:
            merged=seq1
        else:
            l=min(len(seq1), len(seq2))
            merged_chars=[]
            for idx in range(l):
                b1=seq1[idx]; b2=seq2[idx]
                # for stats
                s1=iupac_to_set.get(b1.upper(), {'A','C','G','T'})
                s2=iupac_to_set.get(b2.upper(), {'A','C','G','T'})
                is_het1=len(s1)>1; is_het2=len(s2)>1
                is_hom1=len(s1)==1; is_hom2=len(s2)==1
                if is_hom1 and is_hom2:
                    if s1==s2:
                        same+=1
                    else:
                        diff+=1
                elif is_hom1 and is_het2:
                    hom_het+=1
                elif is_het1 and is_hom2:
                    het_hom+=1
                elif is_het1 and is_het2:
                    het_het+=1

                if intersect:
                    inter=s1 & s2
                    if not inter:
                        merged_chars.append('N')
                    else:
                        merged_chars.append(set_to_iupac.get(frozenset(inter),'N'))
                else:
                    # if identical, keep original (case preserved?)
                    if b1.upper()==b2.upper():
                        merged_chars.append(b1)
                    else:
                        union=s1|s2
                        fs=frozenset(union)
                        # pick IUPAC
                        iup=set_to_iupac.get(fs,'N')
                        if rand_het:
                            # pick random from union
                            chosen=rnd.choice(list(union))
                            # preserve case? Use upper for now
                            merged_chars.append(chosen)
                        else:
                            # preserve case: if both upper, upper, etc. For simplicity upper
                            merged_chars.append(iup)
            if len(seq1)>l:
                merged_chars.extend(list(seq1[l:]))
            elif len(seq2)>l:
                merged_chars.extend(list(seq2[l:]))
            merged=''.join(merged_chars)
            if to_lower:
                new=[]
                for idx,ch in enumerate(merged):
                    b1=seq1[idx] if idx < len(seq1) else 'N'
                    b2=seq2[idx] if idx < len(seq2) else 'N'
                    if b1.upper()=='N' or b2.upper()=='N':
                        new.append(ch.lower())
                    else:
                        new.append(ch)
                merged=''.join(new)
        print(f">{name}\n{merged}")
    sys.stderr.write(f"[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=({same},{diff},{hom_het},{het_hom},{het_het})\n")

def famask_command_real(args):
    if len(args)<2:
        sys.stderr.write("Usage: seqtk famask <src.fa> <mask.fa>\n"); sys.exit(1)
    src=args[0]; mask=args[1]
    def load_dict(fname):
        d={}
        try:
            h=open_file(fname,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
        for rec in parse_fasta_fastq(h):
            d[rec['name']]=rec['seq']
        if h is not sys.stdin:
            h.close()
        return d
    srcd=load_dict(src); maskd=load_dict(mask)
    for name,seq in srcd.items():
        mseq=maskd.get(name,"")
        out=[]
        for idx,ch in enumerate(seq):
            if idx < len(mseq):
                mc=mseq[idx]
                if mc.islower():
