            if output_as_fasta or (not is_fq and not output_as_fastq):
                out.write(f">{out_header}\n")
                if line_len==0:
                    out.write(f"{out_seq}\n")
                else:
                    for k in range(0,len(out_seq),line_len):
                        out.write(f"{out_seq[k:k+line_len]}\n")
            else:
                if not is_fq:
                    qchar=qual_replace if qual_replace else '#'
                    out_qual=qchar*len(out_seq)
                else:
                    if qual_replace is not None:
                        out_qual=qual_replace*len(out_seq)
                    else:
                        out_qual=out_qual if out_qual is not None else qual
                out.write(f"@{out_header}\n")
                if line_len==0:
                    out.write(f"{out_seq}\n")
                else:
                    for k in range(0,len(out_seq),line_len):
                        out.write(f"{out_seq[k:k+line_len]}\n")
                    out.write("+\n")
                    for k in range(0,len(out_qual),line_len):
                        out.write(f"{out_qual[k:k+line_len]}\n")
                    continue
                out.write("+\n")
                out.write(f"{out_qual}\n")
