def sample_command(args):
    seed=11; two_pass=False; i=0; input_file=None; frac_or_num=None
    while i < len(args):
        arg=args[i]
        if arg=='-2':
            two_pass=True; i+=1
        elif arg=='-s':
            i+=1
            if i < len(args):
                try:
                    seed=int(args[i])
                except:
                    seed=11
                i+=1
            else:
                break
        elif arg.startswith('-s'):
            try:
                seed=int(arg[2:])
            except:
                seed=11
            i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"sample: invalid option -- '{arg[1]}'\n"); sys.exit(1)
        else:
            if input_file is None:
                input_file=arg
            elif frac_or_num is None:
                frac_or_num=arg
            i+=1
    if input_file is None or frac_or_num is None:
        sys.stderr.write("Usage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\nOptions: -s INT       RNG seed [11]\n         -2           2-pass mode: twice as slow but with much reduced memory\n")
        sys.exit(1)
    try:
        val=float(frac_or_num)
        is_frac = val < 1.0
        if is_frac:
            frac=val
            num=None
        else:
            is_frac=False
            num=int(val)
    except:
        is_frac=False
        num=0
    if is_frac and two_pass:
        sys.stderr.write("[W::stk_sample] when sampling a fraction, option -2 is ignored.")
    try:
        handle=open_file(input_file,'rt')
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    rnd=random.Random(seed)
    if is_frac:
        for rec in parse_fasta_fastq(handle):
            if rnd.random() < frac:
                if rec['is_fq']:
                    print(f"@{rec['header']}\n{rec['seq']}\n+\n{rec['qual']}")
                else:
                    print(f">{rec['header']}\n{rec['seq']}")
    else:
        k=num
        reservoir=[]
        for idx, rec in enumerate(parse_fasta_fastq(handle)):
            if idx < k:
                reservoir.append(rec)
            else:
                j=rnd.randint(0, idx)
                if j < k:
                    reservoir[j]=rec
        for rec in reservoir:
            if rec['is_fq']:
                print(f"@{rec['header']}\n{rec['seq']}\n+\n{rec['qual']}")
            else:
                print(f">{rec['header']}\n{rec['seq']}")
    if handle is not sys.stdin:
        handle.close()

