            errQ=-10*math.log10(avg_err) if avg_err>0 else 0
            perc_low=pos_low[idx]/cnt*100 if cnt else 0
            perc_high=pos_high[idx]/cnt*100 if cnt else 0
            print(f"{idx+1}\t{cnt}\t{perc_A:.1f}\t{perc_C:.1f}\t{perc_G:.1f}\t{perc_T:.1f}\t{perc_N:.1f}\t{avgQ:.1f}\t{errQ:.1f}\t{perc_low:.1f}\t{perc_high:.1f}")

def mergepe_command(args):
