                    print(f"@{rec['header']}\n{ns}\n+\n{nq}")
                else:
                    print(f">{rec['header']}\n{ns}")
            continue
        if not qual:
            if len(seq)>min_len and min_len>0:
                ns=seq[:min_len]
            else:
                ns=seq
            print(f">{rec['header']}\n{ns}")
            continue
        Q_scores=[ord(c)-33 for c in qual]
        l=0
        while l < len(Q_scores) and Q_scores[l] < Q_thr:
            l+=1
            if len(seq)-l < min_len:
                break
        r=len(Q_scores)-1
        while r>=l and Q_scores[r] < Q_thr:
            r-=1
            if r-l+1 < min_len:
                break
        if l>r:
            ns=""; nq=""
        else:
            ns=seq[l:r+1]; nq=qual[l:r+1]
        if len(ns) > min_len and min_len>0:
            ns=ns[:min_len]; nq=nq[:min_len]
        print(f"@{rec['header']}\n{ns}\n+\n{nq}")
    if handle is not sys.stdin:
        handle.close()

def hety_command_real(args):
    w=50000; t=5; masked=False; i=0; input_file=None
    while i < len(args):
        arg=args[i]
        if arg=='-w':
            i+=1
            if i < len(args):
                try:
                    w=int(args[i])
                except:
                    w=50000
                i+=1
            else:
                break
        elif arg.startswith('-w'):
            try:
                w=int(arg[2:])
            except:
                w=50000
            i+=1
        elif arg=='-t':
            i+=1
            if i < len(args):
                try:
                    t=int(args[i])
                except:
                    t=5
                i+=1
            else:
                break
        elif arg.startswith('-t'):
            try:
                t=int(arg[2:])
            except:
                t=5
            i+=1
        elif arg=='-m':
            masked=True; i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"hety: invalid option -- '{arg[1]}'\n"); sys.exit(1)
        else:
            input_file=arg; i+=1
    if input_file is None:
        handle=sys.stdin
    else:
        try:
