        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    for rec in parse_fasta_fastq(handle):
        seq=rec['seq']
        name=rec['name']
        L=len(seq)
        pos=0
        while pos < L:
            end=min(pos+w, L)
            window_seq=seq[pos:end]
            effective=0
            hets=0
            for b in window_seq:
                if masked and b.islower():
                    continue
                bu=b.upper()
                if bu in "ACGTMRWSYK":
                    effective+=1
                    if bu in "MRWSYK":
                        hets+=1
            rate = (w * hets / effective) if effective>0 else 0
