def dropse_command_real(args):
    if len(args)<1:
        sys.stderr.write("Usage: seqtk dropse <in.fa>\n"); sys.exit(1)
    fname=args[0]
    try:
        handle=open_file(fname,'rt')
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    from collections import defaultdict
    groups=defaultdict(list)
    order=[]
    records=list(parse_fasta_fastq(handle))
    for rec in records:
        hdr=rec['header']; name=rec['name']
        base=hdr
        # Determine base name stripping /1 /2 etc
        # Use name for stripping
        n=name
        if n.endswith('/1') or n.endswith('/2'):
            base=n[:-2]
        elif n.endswith('_1') or n.endswith('_2'):
            base=n[:-2]
        elif n.endswith('.1') or n.endswith('.2'):
            base=n[:-2]
        else:
            # check if header ends with /1 /2
            if hdr.endswith('/1') or hdr.endswith('/2'):
                base=hdr[:-2]
            else:
                base=n
        groups[base].append(rec)
        if base not in order:
            order.append(base)
    for base in order:
        lst=groups[base]
        has1=False; has2=False
        for rec in lst:
            h=rec['header']; n=rec['name']
            if h.endswith('/1') or n.endswith('/1') or '_1' in h or '_1' in n:
                # more precise: ends with /1 or _1 or .1
                if h.endswith('/1') or n.endswith('/1') or h.endswith('_1') or n.endswith('_1') or h.endswith('.1') or n.endswith('.1'):
                    has1=True
            if h.endswith('/2') or n.endswith('/2') or h.endswith('_2') or n.endswith('_2') or h.endswith('.2') or n.endswith('.2'):
                has2=True
        if has1 and has2:
            for rec in lst:
                if rec['is_fq']:
                    print(f"@{rec['header']}\n{rec['seq']}\n+\n{rec['qual']}")
                else:
                    print(f">{rec['header']}\n{rec['seq']}")
    handle.close()

