        for idx,ch in enumerate(seq):
            if ch.upper()=='N':
                if not in_n:
                    in_n=True; start=idx
            else:
                if in_n:
                    in_n=False; end=idx
                    if end-start>=n:
                        tracts.append((start,end))
        if in_n:
            end=len(seq)
            if end-start>=n:
                tracts.append((start,end))
        if gaps_only:
