    i=0; f1=None; f2=None
    while i < len(args):
        arg=args[i]
        if arg=='-q':
            i+=1
            if i < len(args):
                try:
                    q_thr=int(args[i])
                except:
                    q_thr=0
                i+=1
            else:
                break
        elif arg.startswith('-q'):
            try:
                q_thr=int(arg[2:])
            except:
                q_thr=0
            i+=1
        elif arg=='-i':
            intersect=True; i+=1
        elif arg=='-m':
            to_lower=True; i+=1
        elif arg=='-r':
            rand_het=True; i+=1
        elif arg=='-h':
            suppress_hets=True; i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"mergefa: invalid option -- '{arg[1]}'\n"); sys.exit(1)
        else:
            if f1 is None:
                f1=arg
            elif f2 is None:
                f2=arg
            i+=1
    if f1 is None or f2 is None:
        sys.stderr.write("Usage: seqtk mergefa [options] <in1.fa> <in2.fa>\n\nOptions: -q INT   quality threshold [0]\n         -i       take intersection\n         -m       convert to lowercase when one of the input base is N\n         -r       pick a random allele from het\n         -h       suppress hets in the input\n")
        sys.exit(1)
    def load_dict(fname):
        d={}
        try:
            h=open_file(fname,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
        for rec in parse_fasta_fastq(h):
            d[rec['name']]=rec['seq']
        if h is not sys.stdin:
            h.close()
        return d
    dict1=load_dict(f1); dict2=load_dict(f2)
    all_names=set(dict1.keys()) | set(dict2.keys()) if not intersect else set(dict1.keys()) & set(dict2.keys())
    rnd=random.Random(11)
    iupac_to_set={
        'A':{'A'},'C':{'C'},'G':{'G'},'T':{'T'},'U':{'T'},
        'M':{'A','C'},'R':{'A','G'},'W':{'A','T'},'S':{'C','G'},'Y':{'C','T'},'K':{'G','T'},
        'V':{'A','C','G'},'H':{'A','C','T'},'D':{'A','G','T'},'B':{'C','G','T'},'N':{'A','C','G','T'},
    }
    set_to_iupac={
        frozenset({'A'}):'A',
        frozenset({'C'}):'C',
        frozenset({'G'}):'G',
        frozenset({'T'}):'T',
        frozenset({'A','C'}):'M',
        frozenset({'A','G'}):'R',
        frozenset({'A','T'}):'W',
        frozenset({'C','G'}):'S',
        frozenset({'C','T'}):'Y',
        frozenset({'G','T'}):'K',
        frozenset({'A','C','G'}):'V',
        frozenset({'A','C','T'}):'H',
        frozenset({'A','G','T'}):'D',
        frozenset({'C','G','T'}):'B',
        frozenset({'A','C','G','T'}):'N',
    }
    same=0; diff=0; hom_het=0; het_hom=0; het_het=0
    for name in all_names:
        seq1=dict1.get(name,"")
        seq2=dict2.get(name,"")
        if not seq1:
            merged=seq2
        elif not seq2:
            merged=seq1
        else:
            l=min(len(seq1), len(seq2))
            merged_chars=[]
            for idx in range(l):
                b1=seq1[idx]; b2=seq2[idx]
                s1=iupac_to_set.get(b1.upper(), {'A','C','G','T'})
                s2=iupac_to_set.get(b2.upper(), {'A','C','G','T'})
                is_het1=len(s1)>1; is_het2=len(s2)>1
                is_hom1=len(s1)==1; is_hom2=len(s2)==1
                if is_hom1 and is_hom2:
                    if s1==s2:
                        same+=1
                    else:
                        diff+=1
                elif is_hom1 and is_het2:
                    hom_het+=1
                elif is_het1 and is_hom2:
                    het_hom+=1
                elif is_het1 and is_het2:
                    het_het+=1
                if intersect:
                    inter=s1 & s2
                    if not inter:
                        merged_chars.append('N')
                    else:
                        merged_chars.append(set_to_iupac.get(frozenset(inter),'N'))
                else:
                    if b1.upper()==b2.upper():
                        merged_chars.append(b1)
                    else:
                        union=s1|s2
                        if rand_het:
                            chosen=rnd.choice(list(union))
                            merged_chars.append(chosen)
                        else:
                            merged_chars.append(set_to_iupac.get(frozenset(union),'N'))
            if len(seq1)>l:
                merged_chars.extend(list(seq1[l:]))
            elif len(seq2)>l:
                merged_chars.extend(list(seq2[l:]))
            merged=''.join(merged_chars)
            if to_lower:
                new=[]
                for idx,ch in enumerate(merged):
                    b1=seq1[idx] if idx < len(seq1) else 'N'
                    b2=seq2[idx] if idx < len(seq2) else 'N'
                    if b1.upper()=='N' or b2.upper()=='N':
                        new.append(ch.lower())
                    else:
                        new.append(ch)
                merged=''.join(new)
        print(f">{name}\n{merged}")
    sys.stderr.write(f"[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=({same},{diff},{hom_het},{het_hom},{het_het})\n")

def famask_command_real(args):
    if len(args)<2:
