        elif arg.startswith('-q'):
            try:
                qual_thr=int(arg[2:])
            except:
                qual_thr=20
            i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"fqchk: invalid option -- '{arg[1]}'\n"); sys.exit(1)
        else:
            input_file=arg; i+=1
    if input_file is None:
        handle=sys.stdin
    else:
        try:
            handle=open_file(input_file,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    pos_base=[]; pos_qsum=[]; pos_esum=[]; pos_cnt=[]; pos_low=[]; pos_high=[]; pos_qdist=[]
    qual_all=collections.Counter()
    total_len=0; num_seqs=0; min_len=None; max_len=0
    all_base={'A':0,'C':0,'G':0,'T':0,'N':0}
    all_qsum=0; all_esum=0; all_low=0; all_high=0
    for rec in parse_fasta_fastq(handle):
        seq=rec['seq']; qual=rec['qual']
        if not qual:
            continue
        l=len(seq); num_seqs+=1; total_len+=l
        if min_len is None or l<min_len:
            min_len=l
        if l>max_len:
            max_len=l
        while len(pos_base)<l:
            pos_base.append({'A':0,'C':0,'G':0,'T':0,'N':0})
            pos_qsum.append(0)
            pos_esum.append(0)
            pos_cnt.append(0)
            pos_low.append(0)
            pos_high.append(0)
            pos_qdist.append(collections.Counter())
        for idx,b in enumerate(seq):
            bu=b.upper()
            if bu in ('A','C','G','T'):
                pos_base[idx][bu]+=1; all_base[bu]+=1
            else:
                pos_base[idx]['N']+=1; all_base['N']+=1
        for idx,qc in enumerate(qual):
            q=ord(qc)-33
            qual_all[q]+=1
            pos_qdist[idx][q]+=1
            pos_qsum[idx]+=q
            qcapped=max(q,3)
            pos_esum[idx]+=10**(-qcapped/10)
            pos_cnt[idx]+=1
            all_qsum+=q
            all_esum+=10**(-qcapped/10)
            if qual_thr!=0:
                if q < qual_thr:
                    pos_low[idx]+=1; all_low+=1
                else:
                    pos_high[idx]+=1; all_high+=1
    if handle is not sys.stdin:
