def gc_command_real(args):
    at=False; min_frac=0.60; min_len=20; xdrop=10.0; i=0; input_file=None
    while i < len(args):
        arg=args[i]
        if arg=='-w':
            at=True; i+=1
        elif arg=='-f':
            i+=1
            if i < len(args):
                try:
                    min_frac=float(args[i])
                except:
                    min_frac=0.60
                i+=1
            else:
                break
        elif arg.startswith('-f'):
            try:
                min_frac=float(arg[2:])
            except:
                min_frac=0.60
            i+=1
        elif arg=='-l':
            i+=1
            if i < len(args):
                try:
                    min_len=int(args[i])
                except:
                    min_len=20
                i+=1
            else:
                break
        elif arg.startswith('-l'):
            try:
                min_len=int(arg[2:])
            except:
                min_len=20
            i+=1
        elif arg=='-x':
            i+=1
            if i < len(args):
                try:
                    xdrop=float(args[i])
                except:
                    xdrop=10.0
                i+=1
            else:
                break
        elif arg.startswith('-x'):
            try:
                xdrop=float(arg[2:])
            except:
                xdrop=10.0
            i+=1
        elif arg.startswith('-'):
            sys.stderr.write(f"gc: invalid option -- '{arg[1]}'\n"); sys.exit(1)
        else:
            input_file=arg; i+=1
    if input_file is None:
        handle=sys.stdin
    else:
        try:
            handle=open_file(input_file,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    def find_regions(seq, min_frac, min_len, xdrop, at):
        L=len(seq)
        up=seq.upper()
        if at:
            is_gc=[1 if b in 'AT' else 0 for b in up]
        else:
            is_gc=[1 if b in 'GC' else 0 for b in up]
        scores=[g - min_frac for g in is_gc]
        regions=[]
        i=0
        while i < L:
            best_score=-1e9; best_s=-1; best_e=-1
            for start in range(i, L):
                cum=0; max_cum=0; max_end=start
                for end in range(start, L):
                    cum+=scores[end]
                    if cum>max_cum:
                        max_cum=cum
                        max_end=end+1
                    if max_cum - cum > xdrop:
                        break
                if max_cum>best_score and max_end-start>=min_len:
                    best_score=max_cum
                    best_s=start
                    best_e=max_end
            if best_s==-1:
                break
            gc_count=sum(is_gc[best_s:best_e])
            regions.append((best_s,best_e,gc_count))
            i=best_e
        return regions
    for rec in parse_fasta_fastq(handle):
        seq=rec['seq']; name=rec['name']
        regs=find_regions(seq, min_frac, min_len, xdrop, at)
        for s,e,gc_count in regs:
            print(f"{name}\t{s}\t{e}\t{gc_count}")
    if handle is not sys.stdin:
        handle.close()

def mutfa_command_real(args):
    if len(args)<2:
        sys.stderr.write("Usage: seqtk mutfa <in.fa> <in.snp>\n\nNote: <in.snp> contains at least four columns per line which are:\n      'chr  1-based-pos  any  base-changed-to'.\n")
        sys.exit(1)
    fa=args[0]; snp=args[1]
    mut={}
    try:
        with open_file(snp,'rt') as f:
            for line in f:
                line=line.strip()
                if not line or line.startswith('#'):
                    continue
                fields=line.split()
                if len(fields)<4:
                    continue
                chrom=fields[0]
                try:
                    pos=int(fields[1])
                except:
                    continue
                nb=fields[3]
                mut.setdefault(chrom, {})[pos]=nb
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    try:
        handle=open_file(fa,'rt')
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    for rec in parse_fasta_fastq(handle):
        name=rec['name']
        seq=list(rec['seq'])
        if name in mut:
            for p,b in mut[name].items():
                idx=p-1
                if 0 <= idx < len(seq):
                    seq[idx]=b
        print(f">{rec['header']}\n{''.join(seq)}")
    if handle is not sys.stdin:
        handle.close()

