                    val=None
                    if j+1 < len(arg):
                        val=arg[j+1:]; j=len(arg)
                    else:
                        i+=1
                        if i < len(args):
                            val=args[i]
                        else:
                            sys.stderr.write("seq: option requires an argument -- 'n'\n"); sys.exit(1)
                    mask_char=val[0] if val else 'N'
                    break
                elif ch=='F':
                    val=None
                    if j+1 < len(arg):
                        val=arg[j+1:]; j=len(arg)
                    else:
                        i+=1
                        if i < len(args):
                            val=args[i]
                        else:
                            sys.stderr.write("seq: option requires an argument -- 'F'\n"); sys.exit(1)
                    qual_replace=val[0] if val else '#'
                    break
                elif ch=='s':
                    val=None
                    if j+1 < len(arg):
                        val=arg[j+1:]; j=len(arg)
                    else:
                        i+=1
                        if i < len(args):
                            val=args[i]
                        else:
                            sys.stderr.write("seq: option requires an argument -- 's'\n"); sys.exit(1)
                    opt_s=val
                    break
                elif ch=='f':
                    val=None
                    if j+1 < len(arg):
                        val=arg[j+1:]; j=len(arg)
                    else:
                        i+=1
                        if i < len(args):
                            val=args[i]
                        else:
                            sys.stderr.write("seq: option requires an argument -- 'f'\n"); sys.exit(1)
                    opt_f=val
                    break
                elif ch=='X':
                    val=None
                    if j+1 < len(arg):
                        val=arg[j+1:]; j=len(arg)
                    else:
                        i+=1
                        if i < len(args):
                            val=args[i]
                        else:
                            sys.stderr.write("seq: option requires an argument -- 'X'\n"); sys.exit(1)
                    opt_X=val
                    break
                else:
                    sys.stderr.write("seq: invalid option -- '%s'\n" % ch); sys.exit(1)
        else:
            input_file=arg
        i+=1
    bed_dict={}
    if bed_file:
        bed_dict=load_bed(bed_file)
    handle=open_file(input_file,'rt') if input_file else sys.stdin
    out=sys.stdout
    for rec in parse_fasta_fastq(handle):
        seq=rec['seq']; name=rec['name']; header=rec['header']; comment=rec['comment']; is_fq=rec['is_fq']; qual=rec['qual']
        if min_len>0 and len(seq) < min_len:
            continue
        if opt_N and ('N' in seq or 'n' in seq):
            continue
        if bed_dict:
            seq=mask_bed(rec['name'], seq, bed_dict)
        if qual_thr is not None and is_fq and qual:
            new_chars=[]
            for b,qc in zip(seq, qual):
                q=ord(qc)-qual_base
                if q < qual_thr:
                    new_chars.append(mask_char if mask_char else b.lower())
                else:
                    new_chars.append(b)
            seq=''.join(new_chars)
        if opt_U:
            seq=seq.upper()
        output_as_fasta=False
        output_as_fastq=False
        if opt_a or opt_A:
            output_as_fasta=True
        elif qual_replace is not None:
            output_as_fastq=True
        records=[]
        if opt_R:
            records.append((seq, qual, False))
            rc=reverse_complement(seq)
            rq=qual[::-1] if qual else None
            records.append((rc, rq, True))
        elif opt_r:
            rc=reverse_complement(seq)
            rq=qual[::-1] if qual else None
            records.append((rc, rq, True))
        else:
            records.append((seq, qual, False))
        for out_seq, out_qual, is_rc in records:
            out_name=name
            out_header=header
            if opt_R:
                out_name = name + ("-" if is_rc else "+")
                out_header = out_name + (f" {comment}" if comment else "")
            if opt_C:
                out_header=out_name
            if output_as_fasta or (not is_fq and not output_as_fastq):
                out.write(f">{out_header}\n")
                if line_len==0:
                    out.write(f"{out_seq}\n")
                else:
                    for k in range(0,len(out_seq),line_len):
                        out.write(f"{out_seq[k:k+line_len]}\n")
            else:
                if not is_fq:
                    qchar=qual_replace if qual_replace else '#'
                    out_qual=qchar*len(out_seq)
                else:
                    if qual_replace is not None:
                        out_qual=qual_replace*len(out_seq)
                    else:
                        out_qual=out_qual if out_qual is not None else qual
                out.write(f"@{out_header}\n")
                if line_len==0:
                    out.write(f"{out_seq}\n")
                else:
                    for k in range(0,len(out_seq),line_len):
                        out.write(f"{out_seq[k:k+line_len]}\n")
                    out.write("+\n")
                    for k in range(0,len(out_qual),line_len):
                        out.write(f"{out_qual[k:k+line_len]}\n")
                    continue
                out.write("+\n")
                out.write(f"{out_qual}\n")
    if handle is not sys.stdin:
        handle.close()

