def fqchk_command(args):
    qual_thr=20
    i=0
    input_file=None
    while i < len(args):
        arg=args[i]
        if arg=='-q':
            i+=1
            if i < len(args):
                try:
                    qual_thr=int(args[i])
                except:
                    qual_thr=20
                i+=1
            else:
                break
        elif arg.startswith('-q'):
            try:
                qual_thr=int(arg[2:])
            except:
                qual_thr=20
            i+=1
        elif arg.startswith('-'):
            sys.stderr.write("fqchk: invalid option -- '%s'\n" % arg[1]); sys.exit(1)
        else:
            input_file=arg; i+=1
    if input_file is None:
        handle=sys.stdin
    else:
        try:
            handle=open_file(input_file,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    pos_base=[]; pos_qsum=[]; pos_esum=[]; pos_cnt=[]; pos_low=[]; pos_high=[]; pos_qdist=[]
    qual_all=collections.Counter()
    total_len=0; num_seqs=0; min_len=None; max_len=0
    all_base={'A':0,'C':0,'G':0,'T':0,'N':0}
    all_qsum=0; all_esum=0; all_low=0; all_high=0
    for rec in parse_fasta_fastq(handle):
        seq=rec['seq']; qual=rec['qual']
        if not qual:
            continue
        l=len(seq); num_seqs+=1; total_len+=l
        if min_len is None or l<min_len:
            min_len=l
        if l>max_len:
            max_len=l
        while len(pos_base)<l:
            pos_base.append({'A':0,'C':0,'G':0,'T':0,'N':0})
            pos_qsum.append(0)
            pos_esum.append(0)
            pos_cnt.append(0)
            pos_low.append(0)
            pos_high.append(0)
            pos_qdist.append(collections.Counter())
        for idx,b in enumerate(seq):
            bu=b.upper()
            if bu in ('A','C','G','T'):
                pos_base[idx][bu]+=1; all_base[bu]+=1
            else:
                pos_base[idx]['N']+=1; all_base['N']+=1
        for idx,qc in enumerate(qual):
            q=ord(qc)-33
            qual_all[q]+=1
            pos_qdist[idx][q]+=1
            pos_qsum[idx]+=q
            qcapped=max(q,3)
            pos_esum[idx]+=10**(-qcapped/10)
            pos_cnt[idx]+=1
            all_qsum+=q
            all_esum+=10**(-qcapped/10)
            if qual_thr!=0:
                if q < qual_thr:
                    pos_low[idx]+=1; all_low+=1
                else:
                    pos_high[idx]+=1; all_high+=1
    if handle is not sys.stdin:
        handle.close()
    if min_len is None:
        min_len=0; max_len=0; avg_len=0; distinct=0
    else:
        avg_len=total_len/num_seqs if num_seqs else 0
        distinct=len(qual_all)
    if qual_thr==0:
        sorted_q=sorted(qual_all.keys())
        print(f"min_len: {min_len}; max_len: {max_len}; avg_len: {avg_len:.2f}; {distinct} distinct quality values")
        header=["POS","#bases","%A","%C","%G","%T","%N","avgQ","errQ"]+[f"%Q{q}" for q in sorted_q]
        print("\t".join(header))
        total=total_len
        if total>0:
            perc_A=all_base['A']/total*100; perc_C=all_base['C']/total*100; perc_G=all_base['G']/total*100; perc_T=all_base['T']/total*100; perc_N=all_base['N']/total*100
            avgQ=all_qsum/total
            avg_err=all_esum/total
            errQ=-10*math.log10(avg_err) if avg_err>0 else 0
            perc_q=[qual_all[q]/total*100 for q in sorted_q]
            row=[f"ALL",str(total),f"{perc_A:.1f}",f"{perc_C:.1f}",f"{perc_G:.1f}",f"{perc_T:.1f}",f"{perc_N:.1f}",f"{avgQ:.1f}",f"{errQ:.1f}"]+[f"{p:.2f}" for p in perc_q]
            print("\t".join(row))
        else:
            print(f"ALL\t0\t0.0\t0.0\t0.0\t0.0\t0.0\t0.0\t0.0"+ "".join("\t0.00" for _ in sorted_q))
        for idx in range(len(pos_base)):
            cnt=pos_cnt[idx]
            if cnt==0:
                continue
            bc=pos_base[idx]
            perc_A=bc['A']/cnt*100; perc_C=bc['C']/cnt*100; perc_G=bc['G']/cnt*100; perc_T=bc['T']/cnt*100; perc_N=bc['N']/cnt*100
            avgQ=pos_qsum[idx]/cnt if cnt else 0
            avg_err=pos_esum[idx]/cnt if cnt else 0
            errQ=-10*math.log10(avg_err) if avg_err>0 else 0
            perc_q=[pos_qdist[idx][q]/cnt*100 if cnt else 0 for q in sorted_q]
            row=[str(idx+1),str(cnt),f"{perc_A:.1f}",f"{perc_C:.1f}",f"{perc_G:.1f}",f"{perc_T:.1f}",f"{perc_N:.1f}",f"{avgQ:.1f}",f"{errQ:.1f}"]+[f"{p:.2f}" for p in perc_q]
            print("\t".join(row))
    else:
        print(f"min_len: {min_len}; max_len: {max_len}; avg_len: {avg_len:.2f}; {distinct} distinct quality values")
        print("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%low\t%high")
        total=total_len
        if total>0:
            perc_A=all_base['A']/total*100; perc_C=all_base['C']/total*100; perc_G=all_base['G']/total*100; perc_T=all_base['T']/total*100; perc_N=all_base['N']/total*100
            avgQ=all_qsum/total
            avg_err=all_esum/total
            errQ=-10*math.log10(avg_err) if avg_err>0 else 0
            perc_low=all_low/total*100; perc_high=all_high/total*100
            print(f"ALL\t{total}\t{perc_A:.1f}\t{perc_C:.1f}\t{perc_G:.1f}\t{perc_T:.1f}\t{perc_N:.1f}\t{avgQ:.1f}\t{errQ:.1f}\t{perc_low:.1f}\t{perc_high:.1f}")
        else:
            print(f"ALL\t0\t0.0\t0.0\t0.0\t0.0\t0.0\t0.0\t0.0\t0.0\t0.0")
        for idx in range(len(pos_base)):
            cnt=pos_cnt[idx]
            if cnt==0:
                continue
            bc=pos_base[idx]
            perc_A=bc['A']/cnt*100; perc_C=bc['C']/cnt*100; perc_G=bc['G']/cnt*100; perc_T=bc['T']/cnt*100; perc_N=bc['N']/cnt*100
            avgQ=pos_qsum[idx]/cnt if cnt else 0
            avg_err=pos_esum[idx]/cnt if cnt else 0
            errQ=-10*math.log10(avg_err) if avg_err>0 else 0
            perc_low=pos_low[idx]/cnt*100 if cnt else 0
            perc_high=pos_high[idx]/cnt*100 if cnt else 0
            print(f"{idx+1}\t{cnt}\t{perc_A:.1f}\t{perc_C:.1f}\t{perc_G:.1f}\t{perc_T:.1f}\t{perc_N:.1f}\t{avgQ:.1f}\t{errQ:.1f}\t{perc_low:.1f}\t{perc_high:.1f}")

def mergepe_command(args):
