                    n_files=int(args[i])
                except:
                    n_files=10
                i+=1
            else:
                break
        elif arg.startswith('-n'):
            try:
                n_files=int(arg[2:])
            except:
                n_files=10
            i+=1
        elif arg=='-l':
            i+=1
            if i < len(args):
                try:
                    line_len=int(args[i])
                except:
                    line_len=0
                i+=1
            else:
                break
        elif arg.startswith('-l'):
            try:
                line_len=int(arg[2:])
            except:
                line_len=0
            i+=1
