def trimfq_command_real(args):
    q_thr=0.05; min_len=30; left=0; right=0; retain5=0; force_fq=False; i=0; input_file=None
    while i < len(args):
        arg=args[i]
        if arg=='-q':
            i+=1
            if i < len(args):
                try:
                    q_thr=float(args[i])
                except:
                    q_thr=0.05
