    try:
        handle=open_file(fname,'rt')
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    from collections import defaultdict
    groups=defaultdict(list)
    order=[]
    records=list(parse_fasta_fastq(handle))
    for rec in records:
        n=rec['name']
        base=n
        if n.endswith('/1') or n.endswith('/2'):
            base=n[:-2]
        elif n.endswith('_1') or n.endswith('_2'):
            base=n[:-2]
        elif n.endswith('.1') or n.endswith('.2'):
            base=n[:-2]
        groups[base].append(rec)
        if base not in order:
            order.append(base)
    for base in order:
        lst=groups[base]
        has1=False; has2=False
        for rec in lst:
            n=rec['name']
            if n.endswith('/1') or n.endswith('_1') or n.endswith('.1'):
                has1=True
            if n.endswith('/2') or n.endswith('_2') or n.endswith('.2'):
                has2=True
        if has1 and has2:
            for rec in lst:
                if rec['is_fq']:
                    print(f"@{rec['header']}\n{rec['seq']}\n+\n{rec['qual']}")
                else:
                    print(f">{rec['header']}\n{rec['seq']}")
