            if i < len(args):
                try:
                    min_len=int(args[i])
                except:
                    min_len=30
                i+=1
            else:
                break
        elif arg.startswith('-l'):
            try:
                min_len=int(arg[2:])
            except:
                min_len=30
            i+=1
        elif arg=='-b':
            i+=1
            if i < len(args):
                try:
                    left=int(args[i])
                except:
                    left=0
                i+=1
            else:
                break
        elif arg.startswith('-b'):
            try:
                left=int(arg[2:])
            except:
                left=0
            i+=1
        elif arg=='-e':
            i+=1
            if i < len(args):
                try:
                    right=int(args[i])
                except:
                    right=0
                i+=1
            else:
                break
        elif arg.startswith('-e'):
            try:
                right=int(arg[2:])
            except:
                right=0
            i+=1
        elif arg=='-L':
            i+=1
            if i < len(args):
                try:
                    retain5=int(args[i])
                except:
                    retain5=0
                i+=1
            else:
                break
        elif arg.startswith('-L'):
            try:
                retain5=int(arg[2:])
            except:
                retain5=0
            i+=1
        elif arg=='-Q':
            force_fq=True; i+=1
        elif arg.startswith('-'):
            sys.stderr.write("trimfq: invalid option -- '%s'\n" % arg[1]); sys.exit(1)
        else:
            input_file=arg; i+=1
    if input_file is None:
        handle=sys.stdin
    else:
        try:
            handle=open_file(input_file,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    if q_thr>0:
        Q_thr=-10*math.log10(q_thr)
    else:
        Q_thr=0
    for rec in parse_fasta_fastq(handle):
        seq=rec['seq']; qual=rec['qual']; is_fq=rec['is_fq']
        if left>0 or right>0 or retain5>0:
            ns=seq; nq=qual
            if left>0:
                ns=ns[left:]; nq=nq[left:] if nq else nq
            if right>0:
                if right<=len(ns):
                    ns=ns[:-right] if right>0 else ns
                    nq=nq[:-right] if nq and right>0 else nq
                else:
                    ns=""; nq=""
            if retain5>0:
                ns=ns[:retain5]; nq=nq[:retain5] if nq else nq
            if is_fq or force_fq:
                if not nq:
                    nq='I'*len(ns)
                print(f"@{rec['header']}\n{ns}\n+\n{nq}")
            else:
                if force_fq:
                    if not nq:
                        nq='I'*len(ns)
                    print(f"@{rec['header']}\n{ns}\n+\n{nq}")
                else:
                    print(f">{rec['header']}\n{ns}")
            continue
        if not qual:
            if len(seq)>min_len and min_len>0:
                ns=seq[:min_len]
            else:
                ns=seq
            print(f">{rec['header']}\n{ns}")
            continue
        Q_scores=[ord(c)-33 for c in qual]
        l=0
        while l < len(Q_scores) and Q_scores[l] < Q_thr:
            l+=1
            if len(seq)-l < min_len:
                break
        r=len(Q_scores)-1
        while r>=l and Q_scores[r] < Q_thr:
            r-=1
            if r-l+1 < min_len:
                break
        if l>r:
            ns=""; nq=""
        else:
            ns=seq[l:r+1]; nq=qual[l:r+1]
        if len(ns) > min_len and min_len>0:
            ns=ns[:min_len]; nq=nq[:min_len]
        print(f"@{rec['header']}\n{ns}\n+\n{nq}")
    if handle is not sys.stdin:
        handle.close()

