                    effective+=1
                    if bu in "MRWSYK":
                        hets+=1
            rate = (w * hets / effective) if effective>0 else 0
            print(f"{name}\t{pos}\t{end}\t{rate:.2f}\t{effective}\t{hets}")
            pos=end
    if handle is not sys.stdin:
        handle.close()

def gc_command_real(args):
    at=False; min_frac=0.60; min_len=20; xdrop=10.0; i=0; input_file=None
    while i < len(args):
        arg=args[i]
        if arg=='-w':
            at=True; i+=1
        elif arg=='-f':
            i+=1
            if i < len(args):
                try:
                    min_frac=float(args[i])
                except:
                    min_frac=0.60
                i+=1
            else:
                break
        elif arg.startswith('-f'):
            try:
                min_frac=float(arg[2:])
            except:
                min_frac=0.60
            i+=1
        elif arg=='-l':
            i+=1
            if i < len(args):
                try:
                    min_len=int(args[i])
                except:
                    min_len=20
                i+=1
            else:
                break
        elif arg.startswith('-l'):
            try:
                min_len=int(arg[2:])
            except:
                min_len=20
            i+=1
        elif arg=='-x':
            i+=1
            if i < len(args):
                try:
                    xdrop=float(args[i])
                except:
                    xdrop=10.0
                i+=1
            else:
                break
        elif arg.startswith('-x'):
            try:
                xdrop=float(arg[2:])
            except:
                xdrop=10.0
            i+=1
        elif arg.startswith('-'):
            sys.stderr.write("gc: invalid option -- '%s'\n" % arg[1]); sys.exit(1)
        else:
            input_file=arg; i+=1
    if input_file is None:
        handle=sys.stdin
    else:
        try:
            handle=open_file(input_file,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    def find_regions(seq, min_frac, min_len, xdrop, at):
        L=len(seq)
        up=seq.upper()
        if at:
            is_gc=[1 if b in 'AT' else 0 for b in up]
        else:
            is_gc=[1 if b in 'GC' else 0 for b in up]
        scores=[g - min_frac for g in is_gc]
        regions=[]
        start_search=0
        while start_search < L:
            best_score=-1e9; best_s=-1; best_e=-1
            for start in range(start_search, L):
                cum=0; max_cum=0; max_end=start
                for end in range(start, L):
                    cum+=scores[end]
                    if cum>max_cum:
                        max_cum=cum
                        max_end=end+1
                    if max_cum - cum > xdrop:
                        break
                if max_cum>best_score and max_end-start>=min_len:
                    best_score=max_cum
                    best_s=start
                    best_e=max_end
            if best_s==-1:
                break
            gc_count=sum(is_gc[best_s:best_e])
            regions.append((best_s,best_e,gc_count))
            start_search=best_e
        return regions
    for rec in parse_fasta_fastq(handle):
        seq=rec['seq']; name=rec['name']
        regs=find_regions(seq, min_frac, min_len, xdrop, at)
        for s,e,gc_count in regs:
            print(f"{name}\t{s}\t{e}\t{gc_count}")
    if handle is not sys.stdin:
        handle.close()

def mutfa_command_real(args):
    if len(args)<2:
        sys.stderr.write("Usage: seqtk mutfa <in.fa> <in.snp>\n\nNote: <in.snp> contains at least four columns per line which are:\n      'chr  1-based-pos  any  base-changed-to'.\n")
        sys.exit(1)
    fa=args[0]; snp=args[1]
    mut={}
    try:
        with open_file(snp,'rt') as f:
            for line in f:
                line=line.strip()
                if not line or line.startswith('#'):
                    continue
                fields=line.split()
                if len(fields)<4:
                    continue
                chrom=fields[0]
                try:
                    pos=int(fields[1])
                except:
                    continue
                nb=fields[3]
                mut.setdefault(chrom, {})[pos]=nb
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    try:
        handle=open_file(fa,'rt')
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    for rec in parse_fasta_fastq(handle):
        name=rec['name']
        seq=list(rec['seq'])
        if name in mut:
            for p,b in mut[name].items():
                idx=p-1
                if 0 <= idx < len(seq):
                    seq[idx]=b
        print(f">{rec['header']}\n{''.join(seq)}")
    if handle is not sys.stdin:
        handle.close()

def mergefa_command_real(args):
    q_thr=0; intersect=False; to_lower=False; rand_het=False; suppress_hets=False
    i=0; f1=None; f2=None
    while i < len(args):
        arg=args[i]
        if arg=='-q':
            i+=1
            if i < len(args):
                try:
                    q_thr=int(args[i])
                except:
                    q_thr=0
                i+=1
            else:
                break
        elif arg.startswith('-q'):
            try:
                q_thr=int(arg[2:])
            except:
                q_thr=0
            i+=1
        elif arg=='-i':
            intersect=True; i+=1
        elif arg=='-m':
            to_lower=True; i+=1
        elif arg=='-r':
            rand_het=True; i+=1
        elif arg=='-h':
            suppress_hets=True; i+=1
        elif arg.startswith('-'):
            sys.stderr.write("mergefa: invalid option -- '%s'\n" % arg[1]); sys.exit(1)
        else:
            if f1 is None:
                f1=arg
            elif f2 is None:
                f2=arg
            i+=1
    if f1 is None or f2 is None:
        sys.stderr.write("Usage: seqtk mergefa [options] <in1.fa> <in2.fa>\n\nOptions: -q INT   quality threshold [0]\n         -i       take intersection\n         -m       convert to lowercase when one of the input base is N\n         -r       pick a random allele from het\n         -h       suppress hets in the input\n")
        sys.exit(1)
    def load_dict(fname):
        d={}
        try:
            h=open_file(fname,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
        for rec in parse_fasta_fastq(h):
            d[rec['name']]=rec['seq']
        if h is not sys.stdin:
            h.close()
        return d
    dict1=load_dict(f1); dict2=load_dict(f2)
    all_names=set(dict1.keys()) | set(dict2.keys()) if not intersect else set(dict1.keys()) & set(dict2.keys())
    rnd=random.Random(11)
    iupac_to_set={
        'A':{'A'},'C':{'C'},'G':{'G'},'T':{'T'},'U':{'T'},
        'M':{'A','C'},'R':{'A','G'},'W':{'A','T'},'S':{'C','G'},'Y':{'C','T'},'K':{'G','T'},
        'V':{'A','C','G'},'H':{'A','C','T'},'D':{'A','G','T'},'B':{'C','G','T'},'N':{'A','C','G','T'},
    }
    set_to_iupac={
        frozenset({'A'}):'A',
        frozenset({'C'}):'C',
        frozenset({'G'}):'G',
        frozenset({'T'}):'T',
        frozenset({'A','C'}):'M',
        frozenset({'A','G'}):'R',
        frozenset({'A','T'}):'W',
        frozenset({'C','G'}):'S',
        frozenset({'C','T'}):'Y',
        frozenset({'G','T'}):'K',
        frozenset({'A','C','G'}):'V',
        frozenset({'A','C','T'}):'H',
        frozenset({'A','G','T'}):'D',
        frozenset({'C','G','T'}):'B',
        frozenset({'A','C','G','T'}):'N',
    }
    same=0; diff=0; hom_het=0; het_hom=0; het_het=0
    for name in sorted(all_names):
        seq1=dict1.get(name,"")
        seq2=dict2.get(name,"")
        if not seq1:
            merged=seq2
        elif not seq2:
            merged=seq1
        else:
            l=min(len(seq1), len(seq2))
            merged_chars=[]
            for idx in range(l):
                b1=seq1[idx]; b2=seq2[idx]
                s1=iupac_to_set.get(b1.upper(), {'A','C','G','T'})
                s2=iupac_to_set.get(b2.upper(), {'A','C','G','T'})
                is_het1=len(s1)>1; is_het2=len(s2)>1
                is_hom1=len(s1)==1; is_hom2=len(s2)==1
                if is_hom1 and is_hom2:
                    if s1==s2:
                        same+=1
                    else:
                        diff+=1
                elif is_hom1 and is_het2:
                    hom_het+=1
                elif is_het1 and is_hom2:
                    het_hom+=1
                elif is_het1 and is_het2:
                    het_het+=1
                if intersect:
                    inter=s1 & s2
                    if not inter:
                        merged_chars.append('N')
                    else:
                        merged_chars.append(set_to_iupac.get(frozenset(inter),'N'))
                else:
                    if b1.upper()==b2.upper():
                        merged_chars.append(b1)
                    else:
                        union=s1|s2
                        if rand_het:
                            chosen=rnd.choice(list(union))
                            merged_chars.append(chosen)
                        else:
                            merged_chars.append(set_to_iupac.get(frozenset(union),'N'))
            if len(seq1)>l:
                merged_chars.extend(list(seq1[l:]))
            elif len(seq2)>l:
                merged_chars.extend(list(seq2[l:]))
            merged=''.join(merged_chars)
            if to_lower:
                new=[]
                for idx,ch in enumerate(merged):
                    b1=seq1[idx] if idx < len(seq1) else 'N'
                    b2=seq2[idx] if idx < len(seq2) else 'N'
                    if b1.upper()=='N' or b2.upper()=='N':
                        new.append(ch.lower())
                    else:
                        new.append(ch)
                merged=''.join(new)
        print(f">{name}\n{merged}")
    sys.stderr.write(f"[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=({same},{diff},{hom_het},{het_hom},{het_het})\n")

def famask_command_real(args):
    if len(args)<2:
        sys.stderr.write("Usage: seqtk famask <src.fa> <mask.fa>\n"); sys.exit(1)
    src=args[0]; mask=args[1]
    def load_dict(fname):
        d={}
        try:
            h=open_file(fname,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
        for rec in parse_fasta_fastq(h):
            d[rec['name']]=rec['seq']
        if h is not sys.stdin:
            h.close()
        return d
    srcd=load_dict(src); maskd=load_dict(mask)
    for name,seq in srcd.items():
        mseq=maskd.get(name,"")
        out=[]
        for idx,ch in enumerate(seq):
            if idx < len(mseq):
                mc=mseq[idx]
                if mc.islower():
                    out.append(ch.lower())
                else:
                    out.append(ch.upper())
            else:
                out.append(ch)
        print(f">{name}\n{''.join(out)}")

def dropse_command_real(args):
    if len(args)<1:
        sys.stderr.write("Usage: seqtk dropse <in.fa>\n"); sys.exit(1)
    fname=args[0]
    try:
        handle=open_file(fname,'rt')
    except:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    from collections import defaultdict
    groups=defaultdict(list)
    order=[]
    records=list(parse_fasta_fastq(handle))
    for rec in records:
        n=rec['name']
        base=n
        if n.endswith('/1') or n.endswith('/2'):
            base=n[:-2]
        elif n.endswith('_1') or n.endswith('_2'):
            base=n[:-2]
        elif n.endswith('.1') or n.endswith('.2'):
            base=n[:-2]
        groups[base].append(rec)
        if base not in order:
            order.append(base)
    for base in order:
        lst=groups[base]
        has1=False; has2=False
        for rec in lst:
            n=rec['name']
            if n.endswith('/1') or n.endswith('_1') or n.endswith('.1'):
                has1=True
            if n.endswith('/2') or n.endswith('_2') or n.endswith('.2'):
                has2=True
        if has1 and has2:
            for rec in lst:
                if rec['is_fq']:
                    print(f"@{rec['header']}\n{rec['seq']}\n+\n{rec['qual']}")
                else:
                    print(f">{rec['header']}\n{rec['seq']}")
    handle.close()

