def cutN_command_real(args):
    n=1000; penalty=10; gaps_only=False; i=0; input_file=None
    while i < len(args):
        arg=args[i]
        if arg=='-n':
            i+=1
            if i < len(args):
                try:
                    n=int(args[i])
                except:
                    n=1000
                i+=1
            else:
                break
        elif arg.startswith('-n'):
            try:
                n=int(arg[2:])
            except:
                n=1000
            i+=1
        elif arg=='-p':
            i+=1
            if i < len(args):
                try:
                    penalty=int(args[i])
                except:
                    penalty=10
                i+=1
            else:
                break
        elif arg.startswith('-p'):
            try:
                penalty=int(arg[2:])
            except:
                penalty=10
            i+=1
        elif arg=='-g':
            gaps_only=True; i+=1
        elif arg.startswith('-'):
            sys.stderr.write("cutN: invalid option -- '%s'\n" % arg[1]); sys.exit(1)
        else:
            input_file=arg; i+=1
    if input_file is None:
        handle=sys.stdin
    else:
        try:
            handle=open_file(input_file,'rt')
        except:
            sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n"); sys.exit(1)
    for rec in parse_fasta_fastq(handle):
        seq=rec['seq']; name=rec['name']
        tracts=[]
        in_n=False; start=0
        for idx,ch in enumerate(seq):
            if ch.upper()=='N':
                if not in_n:
                    in_n=True; start=idx
            else:
                if in_n:
                    in_n=False; end=idx
                    if end-start>=n:
                        tracts.append((start,end))
        if in_n:
            end=len(seq)
            if end-start>=n:
                tracts.append((start,end))
        if gaps_only:
            for s,e in tracts:
                print(f"{name}\t{s}\t{e}")
        else:
            prev=0
            for s,e in tracts:
                if s>prev:
                    sub=seq[prev:s]
                    print(f">{name}:{prev+1}-{s}\n{sub}")
                prev=e
            if prev < len(seq):
                sub=seq[prev:]
                print(f">{name}:{prev+1}-{len(seq)}\n{sub}")
    if handle is not sys.stdin:
        handle.close()

